head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
scwin.vBzProcsNo = "";
scwin.vAcptNo = "";
scwin.vIsurCd = "";
scwin.vOpenTyp = "";
// 세션정보를 얻기위한 함수사용
scwin.getPar, scwin.setPar;
scwin.dts_Recv;
scwin.TR_JOB;
scwin.VListBzTpCd = LIST_BZ_TP_CD_143;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // var parentWin = fn_GetProvider();
        const parentWin = $c.frame.path("../");
        // alert('[parentWin]'+parentWin);
        scwin.dts_Recv = parentWin.scwin.dts_Recv;
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        scwin.vAcptNo = parentWin.scwin.vAcptNo;
        scwin.vIsurCd = parentWin.scwin.vIsurCd;
        scwin.vOpenTyp = parentWin.scwin.vOpenTyp;
        txb_ISU_CD.setValue(parentWin.txb_ISU_CD.getValue());
        txb_ISU_NM.setValue(parentWin.txb_ISU_NM.getValue());
        $c.libRoundPanel.PanelToGroupBox(panel_Item);

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성s
        // buttonSet.setDrftInfo( btn_Drft, fn_drft );            // 기안

        if (scwin.vOpenTyp === "R") {
            await scwin.setHeader();
            await scwin.recvReadSync(scwin.dts_Recv.getFocusedRowIndex());
            buttonSet.setInsertStatus();
        } else if (scwin.vOpenTyp === "H") {
            await scwin.readSync();
        } else if (scwin.vOpenTyp === "N") {
            await scwin.setHeader();
            await scwin.bfReadSync();
            scwin.initItem();
        }
        buttonSet.setButtonSecugrpDepCd(dts_ByCorpDepCd, SECUGRP_ID_BC, scwin.vIsurCd, js_dep_cd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05414.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name edt_INCDEC_TOT_STKCNT_onkillfocus
 * @description edt_INCDEC_TOT_STKCNT onkillfocus 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.edt_INCDEC_TOT_STKCNT_onkillfocus = async function() {
    try {
        await scwin.calTotStkCnt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05414.edt_INCDEC_TOT_STKCNT_onkillfocus" });
    }
};

/**
 * @method
 * @name edt_INCDEC_TRST_ORGN_VAL_onkillfocus
 * @description edt_INCDEC_TRST_ORGN_VAL onkillfocus 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.edt_INCDEC_TRST_ORGN_VAL_onkillfocus = async function() {
    try {
        await scwin.calTrstOrgnVal();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05414.edt_INCDEC_TRST_ORGN_VAL_onkillfocus" });
    }
};

/**
 * @method
 * @name img_LIST_DD_onclick
 * @description img_LIST_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_LIST_DD_onclick = function() {
    try {
        popUpCalendar2(edt_LIST_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05414.img_LIST_DD_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05414.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_RecvIsuDel_onclick
 * @description 「신청종목삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_RecvIsuDel_onclick = async function() {
    try {
        await scwin.recvtIsuDel();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05414.btn_RecvIsuDel_onclick" });
    }
};

/**
 * @method
 * @name dts_Bf_Isu_OnLoadError
 * @description dts_Bf_Isu 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Bf_Isu_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Bf_Isu);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05414.dts_Bf_Isu_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadError
 * @description dts_Isu 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Isu_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Isu);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05414.dts_Isu_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vOpenTyp === "N" || (scwin.vOpenTyp === "R" && scwin.vBzProcsNo === '')) {
            buttonSet.setInsertStatus();
        } else {
            $c.stf.setButtonSetWithDate(edt_LIST_DD, false);
            $c.stf.setButtonSetWithDate2(dts_Isu.getCellData(1, "DISCLS_YN"));
        }
        if (scwin.vOpenTyp === "R" && scwin.vBzProcsNo === "") {
            btn_RecvIsuDel.setBackgroundImage("../img/btn_RcvdocDel.gif");
            btn_RecvIsuDel.setDisabled(false);
        } else {
            btn_RecvIsuDel.setBackgroundImage("../img/btn_RcvdocDel_d.gif");
            btn_RecvIsuDel.setDisabled(true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05414.dts_Isu_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05414.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        scwin.parentRefresh(); // 목록 다시 조회

        if (scwin.TR_JOB === 'D') {
            await $c.win.closePopup();
        } else {
            await scwin.readSync();
            buttonSet.setUpdateStatus();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05414.trs_Save_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Isu.insertRow();
    // alert(dts_Isu.text+" dts_Isu.text");

};

/**
 * @method
 * @name bfReadSync
 * @description bf Read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.bfReadSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05414.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_CHG_ISS_BC_HIST + "&TRS_IDX=" + TRS_IDX_NEWSEL2 + "&ISU_CD=" + txb_ISU_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_Bf_Isu",
        action : "/Listing.do",
        ref : "",
        target : "dts_Bf_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Isu.setCellData(1, "BFCHG_TRST_ORGN_VAL", dts_Bf_Isu.getCellData(1, "BFCHG_TRST_ORGN_VAL"));
    dts_Isu.setCellData(1, "BFCHG_TOT_STKCNT", dts_Bf_Isu.getCellData(1, "BFCHG_TOT_STKCNT"));
};

/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function(row) {
    url += "?SCREN_ID=" + "ULDSTF05414.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_CHG_ISS_BC_HIST + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/Listing.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} trsIdx trsIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(trsIdx) {
    if (trsIdx === '1') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (trsIdx === '2') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (trsIdx === '3') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }

    // alert("[fn_trs vBzProcsNo] ."+vBzProcsNo);
    // dts_Isu.NameValue(1, "JOB_TYPE") = trsIdx;
    dts_Isu.setCellData(1, "ISUR_CD", scwin.vIsurCd);
    dts_Isu.setCellData(1, "ISU_CD", txb_ISU_CD.getValue());
    dts_Isu.setCellData(1, "LIST_BZ_TP_CD", scwin.VListBzTpCd);
    // alert('[dts_Isu]'+dts_Isu.text);

    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : trsIdx,
    //     ACPT_NO : scwin.vAcptNo,
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     COUNT : "1",
    //     LIST_BZ_TP_CD : scwin.VListBzTpCd + ",DIV_IDX[0]=" + DIV_IDX_CHG_ISS_BC_HIST
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/Listing.do",
        ref : "dts_Isu",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initItem
 * @description 수익증권 변경상장
 * @returns {void}
 * @hidden N
 */
scwin.initItem = function() {
    cmb_LIST_METHD_TP_CD.setValue(LIST_METHD_TP_CD_3);
    txb_ISU_RSN_CONTN.setValue("수익증권 일부 중도환수");
};

/**
 * @method
 * @name calTrstOrgnVal
 * @description cal Trst Orgn Val 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calTrstOrgnVal = async function() {
    try {
        let vsum = parseInt(edt_BFCHG_TRST_ORGN_VAL.getValue(), 10) + parseInt(edt_INCDEC_TRST_ORGN_VAL.getValue(), 10);
        edt_AFCHG_TRST_ORGN_VAL.setValue(vsum);
    } catch (err) {
        await $c.win.alert("[증권수 합산처리 중  오류]");
    }
};

/**
 * @method
 * @name calTotStkCnt
 * @description cal Tot Stk Cnt 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calTotStkCnt = async function() {
    try {
        let vsum = parseInt(edt_BFCHG_TOT_STKCNT.getValue(), 10) + parseInt(edt_INCDEC_TOT_STKCNT.getValue(), 10);
        edt_AFCHG_TOT_STKCNT.setValue(vsum);
    } catch (err) {
        await $c.win.alert("[증권수 합산처리 중  오류]");
    }
};

/**
 * @method
 * @name recvReadSync
 * @description recv Read Sync 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.recvReadSync = async function(row) {
    dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.dts_Recv.getCellData(row, "BZ_PROCS_NO"));
    dts_Isu.setCellData(1, "ACPT_NO", scwin.dts_Recv.getCellData(row, "ACPT_NO"));
    await scwin.bfReadSync();
    dts_Isu.setCellData(1, "INCDEC_TRST_ORGN_VAL", scwin.dts_Recv.getCellData(row, "INCDEC_TRST_ORGN_VAL"));
    dts_Isu.setCellData(1, "INCDEC_TOT_STKCNT", scwin.dts_Recv.getCellData(row, "INCDEC_TOT_STKCNT"));
    await scwin.calTrstOrgnVal();
    await scwin.calTotStkCnt();
    dts_Isu.setCellData(1, "REMK", scwin.dts_Recv.getCellData(scwin.dts_Recv.getFocusedRowIndex(), "REMK"));
    scwin.initItem();
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if (edt_LIST_DD.getValue() === "") {
        await $c.win.alert("[변경상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (vCurDate >= edt_LIST_DD.getValue()) {
        await $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (cmb_LIST_METHD_TP_CD.getValue() === "") {
        await $c.win.alert("[상장방식]을 선택하세요.");
        cmb_LIST_METHD_TP_CD.focus();
        return false;
    }
    if (edt_INCDEC_TRST_ORGN_VAL.getValue() === "") {
        await $c.win.alert("[증감 신탁원본액]을 입력하세요.");
        edt_INCDEC_TRST_ORGN_VAL.focus();
        return false;
    }
    // if (! fn_checkNumber(edt_INCDEC_TRST_ORGN_VAL, '증감 신탁원본액')) return false;

    if (edt_AFCHG_TRST_ORGN_VAL.getValue() === "") {
        await $c.win.alert("[변경후 신탁원본액]을 입력하세요.");
        edt_AFCHG_TRST_ORGN_VAL.focus();
        return false;
    }
    // if (! fn_checkNumber(edt_AFCHG_TRST_ORGN_VAL, '변경후 신탁원본액')) return false;

    if (edt_INCDEC_TOT_STKCNT.getValue() === "") {
        await $c.win.alert("[증감 좌수]를 입력하세요.");
        edt_INCDEC_TOT_STKCNT.focus();
        return false;
    }
    // if (! fn_checkNumber(edt_INCDEC_TOT_STKCNT, '증감 좌수')) return false;

    if (edt_AFCHG_TOT_STKCNT.getValue() === "") {
        await $c.win.alert("[변경후 총좌수]를 입력하세요.");
        edt_AFCHG_TOT_STKCNT.focus();
        return false;
    }
    // if (! fn_checkNumber(edt_AFCHG_TOT_STKCNT, '변경후 총좌수')) return false;

    if (txb_ISU_RSN_CONTN.getValue() === "") {
        await $c.win.alert("[변경사유]를 입력하세요.");
        txb_ISU_RSN_CONTN.focus();
        return false;
    }
    if (txa_REMK.getValue().length > 500) {
        await $c.win.alert("[비고]항목이 입력사이즈를 초과하였씁니다.");
        txa_REMK.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name checkNumber
 * @description check Number 처리
 * @param {Object} obj 컴포넌트
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.checkNumber = function(obj, str) {
    /*
    if (getObjectValue(obj) <= 100) {
    	alert("["+str+"]를 '"+getObjectValue(obj)+"'으로 입력하셨습니다. 확인 후 재입력바랍니다.");obj.focus();return false;
    }
     */
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        if (scwin.vAcptNo === "") {
            scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        }
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            // dts_Isu.UserStatus(1) = TB_JOB_INSERT;
            dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            await scwin.trs(TRS_IDX_INSERT);
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        await scwin.trs(TRS_IDX_UPDATE);
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    scwin.TR_JOB = 'D';
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    await scwin.trs(TRS_IDX_DELETE);
};

/**
 * @method
 * @name recvtIsuDel
 * @description recvt Isu Del 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.recvtIsuDel = async function() {
    if (scwin.vAcptNo === "") {
        await $c.win.alert('발행예정내역에서 대상종목을 선택하세요');
        return;
    }
    await scwin.delete();
};

/**
 * @method
 * @name dateForm
 * @description date Form 처리
 * @param {String} pStr pStr
 * @returns {void}
 * @hidden N
 */
scwin.dateForm = function(pStr) {
    let str = "";
    if (pStr === "") {
        str = "★★★★년" + "★★월" + "★★일";
    } else {
        str = pStr.substring(0, 4) + "년" + pStr.substring(4, 6) + "월" + pStr.substring(6, 8) + "일";
    }
    return str;
};

// 2010.03.29 변경신탁원본액과, 수익증권총좌수 추가 (INCDEC_TRST_ORGN_VAL, INCDEC_TOT_STKCNT)

/**
 * @method
 * @name dsclCtnt
 * @description dscl Ctnt 처리
 * @returns {void}
 * @hidden N
 */
scwin.dsclCtnt = function() {
    let vCtnt = "";
    vCtnt += "◎ " + txb_ISU_NM.getValue() + " 변경상장 내역";
    vCtnt += "\r\n";
    vCtnt += "① 구분(변경전 -> 변경후)";
    vCtnt += "\r\n";
    vCtnt += "    ㉮ 신탁원본액 : " + $c.stf.addComma(dts_Isu.getCellData(1, "BFCHG_TRST_ORGN_VAL")) + "원 -> " + $c.stf.addComma(dts_Isu.getCellData(1, "AFCHG_TRST_ORGN_VAL")) + "원 (" + $c.stf.addCommaMinus(dts_Isu.getCellData(1, "INCDEC_TRST_ORGN_VAL")) + "원)";
    vCtnt += "\r\n";
    vCtnt += "    ㉯ 수익증권총좌수 : " + $c.stf.addComma(dts_Isu.getCellData(1, "BFCHG_TOT_STKCNT")) + "좌 -> " + $c.stf.addComma(dts_Isu.getCellData(1, "AFCHG_TOT_STKCNT")) + "좌 (" + $c.stf.addCommaMinus(dts_Isu.getCellData(1, "INCDEC_TOT_STKCNT")) + "좌)";
    vCtnt += "\r\n";
    vCtnt += "② 1좌당 원본액 : " + $c.stf.addComma(dts_Isu.getCellData(1, "PARVAL")) + "원";
    vCtnt += "\r\n";
    vCtnt += "③ 변경상장일 : " + scwin.dateForm(dts_Isu.getCellData(1, "LIST_DD"));
    vCtnt += "\r\n";
    vCtnt += "④ 변경사유 : " + dts_Isu.getCellData(1, "ISU_RSN_CONTN");
    vCtnt += "\r\n";
    vCtnt += "⑤ 표준코드 : " + dts_Isu.getCellData(1, "ISU_CD") + " (단축코드:" + dts_Isu.getCellData(1, "ISU_SRT_CD") + ")";
    // alert(vCtnt);
    return vCtnt;
};

